import { test, expect } from '@playwright/test';

test.describe('Click Target Size Accessibility for Users with Motor Impairment', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/accessibility-test-page');
  });

  test('should have click targets with minimum size of 44x44px for users with motor impairment', async ({ page }) => {
    // Verify the page has a role of main
    const mainRole = page.getByRole('main');
    await expect(mainRole).toBeVisible();

    // Verify button has a minimum size of 44x44px
    const button = page.getByRole('button', { name: /submit form/i });
    await expect(button).toBeVisible();
    const buttonSize = await button.boundingBox();
    expect(buttonSize.width).toBeGreaterThanOrEqual(44);
    expect(buttonSize.height).toBeGreaterThanOrEqual(44);

    // Verify link has a minimum size of 44x44px
    const link = page.getByRole('link', { name: /download file/i });
    await expect(link).toBeVisible();
    const linkSize = await link.boundingBox();
    expect(linkSize.width).toBeGreaterThanOrEqual(44);
    expect(linkSize.height).toBeGreaterThanOrEqual(44);

    // Verify input has a minimum size of 44x44px
    const input = page.getByLabel(/email address/i);
    await expect(input).toBeVisible();
    const inputSize = await input.boundingBox();
    expect(inputSize.width).toBeGreaterThanOrEqual(44);
    expect(inputSize.height).toBeGreaterThanOrEqual(44);

    // Verify checkbox has a minimum size of 44x44px
    const checkbox = page.getByLabel(/agree to terms/i);
    await expect(checkbox).toBeVisible();
    const checkboxSize = await checkbox.boundingBox();
    expect(checkboxSize.width).toBeGreaterThanOrEqual(44);
    expect(checkboxSize.height).toBeGreaterThanOrEqual(44);

    // Verify dropdown has a minimum size of 44x44px
    const dropdown = page.getByRole('combobox', { name: /select plan/i });
    await expect(dropdown).toBeVisible();
    const dropdownSize = await dropdown.boundingBox();
    expect(dropdownSize.width).toBeGreaterThanOrEqual(44);
    expect(dropdownSize.height).toBeGreaterThanOrEqual(44);

    // Verify error message has a minimum size of 44x44px
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).toBeVisible();
    const errorMessageSize = await errorMessage.boundingBox();
    expect(errorMessageSize.width).toBeGreaterThanOrEqual(44);
    expect(errorMessageSize.height).toBeGreaterThanOrEqual(44);
  });

  test('should handle click targets with sizes smaller than 44x44px gracefully', async ({ page }) => {
    // Verify page has a role of main
    const mainRole = page.getByRole('main');
    await expect(mainRole).toBeVisible();

    // Verify button with size smaller than 44x44px
    const smallButton = page.getByRole('button', { name: /submit form/i });
    await expect(smallButton).toBeVisible();
    const smallButtonSize = await smallButton.boundingBox();
    expect(smallButtonSize.width).toBeLessThan(44);
    expect(smallButtonSize.height).toBeLessThan(44);

    // Verify link with size smaller than 44x44px
    const smallLink = page.getByRole('link', { name: /download file/i });
    await expect(smallLink).toBeVisible();
    const smallLinkSize = await smallLink.boundingBox();
    expect(smallLinkSize.width).toBeLessThan(44);
    expect(smallLinkSize.height).toBeLessThan(44);

    // Verify input with size smaller than 44x44px
    const smallInput = page.getByLabel(/email address/i);
    await expect(smallInput).toBeVisible();
    const smallInputSize = await smallInput.boundingBox();
    expect(smallInputSize.width).toBeLessThan(44);
    expect(smallInputSize.height).toBeLessThan(44);

    // Verify checkbox with size smaller than 44x44px
    const smallCheckbox = page.getByLabel(/agree to terms/i);
    await expect(smallCheckbox).toBeVisible();
    const smallCheckboxSize = await smallCheckbox.boundingBox();
    expect(smallCheckboxSize.width).toBeLessThan(44);
    expect(smallCheckboxSize.height).toBeLessThan(44);

    // Verify dropdown with size smaller than 44x44px
    const smallDropdown = page.getByRole('combobox', { name: /select plan/i });
    await expect(smallDropdown).toBeVisible();
    const smallDropdownSize = await smallDropdown.boundingBox();
    expect(smallDropdownSize.width).toBeLessThan(44);
    expect(smallDropdownSize.height).toBeLessThan(44);

    // Verify error message with size smaller than 44x44px
    const smallErrorMessage = page.getByText(/error/i);
    await expect(smallErrorMessage).toBeVisible();
    const smallErrorMessageSize = await smallErrorMessage.boundingBox();
    expect(smallErrorMessageSize.width).toBeLessThan(44);
    expect(smallErrorMessageSize.height).toBeLessThan(44);

    // Verify error message is still visible and accessible
    const errorMessageText = await smallErrorMessage.textContent();
    expect(errorMessageText).toContain('error');

    // Verify error message is still accessible via screen readers
    const errorMessageSpeak = await page.evaluate(() => {
      const errorMessage = document.querySelector('[aria-live="polite"]');
      if (errorMessage) {
        return errorMessage.textContent;
      }
      return '';
    });
    expect(errorMessageSpeak).toContain('error');
  });
});
